function pickMeta(
  record: { meta_data: Array<{ key: string; value: unknown }> },
  key: string,
): { present: false } | { present: true; value: unknown } {
  const entry = record.meta_data.find((m) => m.key === key);
  return entry === undefined
    ? { present: false }
    : { present: true, value: entry.value };
}

